{
  "findings": [
    {
      "check_id": "CKV_AWS_8",
      "title": "Ensure all data stored in the Launch configuration or instance Elastic Blocks Store is securely encrypted",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "MEDIUM",
      "explanation": "The launch configuration does not specify `root_block_device` with `encrypted = true`, meaning the root EBS volume for instances launched by this configuration will not be encrypted at rest."
    },
    {
      "check_id": "AVD-AWS-0130",
      "title": "Launch configuration does not require IMDS access to require a token",
      "resource": "aws_launch_configuration.levelup-launchconfig",
      "severity": "HIGH",
      "explanation": "The launch configuration lacks an `ebs_optimized` block or metadata options enforcing IMDSv2. Without `metadata_options { http_tokens = \"required\" }`, instances are vulnerable to SSRF attacks via the Instance Metadata Service (IMDSv1)."
    }
  ],
  "patched_code": "resource \"aws_launch_configuration\" \"levelup-launchconfig\" {\n  name_prefix     = \"levelup-launchconfig\"\n  image_id        = lookup(var.AMIS, var.AWS_REGION)\n  instance_type   = \"t2.micro\"\n  key_name        = aws_key_pair.levelup_key.key_name\n\n  root_block_device {\n    encrypted = true\n  }\n\n  metadata_options {\n    http_endpoint = \"enabled\"\n    http_tokens   = \"required\"\n  }\n}",
  "fix_summary": "Added `root_block_device` with `encrypted = true` to ensure EBS volumes are encrypted at rest. Added `metadata_options` with `http_tokens = \"required\"` to enforce IMDSv2 and mitigate SSRF risks."
}
